  "supportive_card_ids": ["C02","C09","C21","C30","C87","C89","C141","C165","C175","C199","C192","C182"],
  "contradictory_card_ids": ["C181","C187","C194","C218","C211","C186","C201"],
  "prediction_basis_card_ids": ["C02","C09","C21","C87","C89","C141","C165","C175"],
  "claims": [
    {
      "claim": "Direct human gold records for the fluoroquinolone class show high absolute oral bioavailability: ofloxacin 80-95% in CF patients (C30), ~91% in patients (C02), approaching 100% fasted (C11), levofloxacin ~100% (C21), trovafloxacin 87.6% (C09), and antofloxacin high (C19/C33).",
      "card_ids": ["C30","C02","C11","C21","C09","C19","C33"]
    },
    {
      "claim": "Moxifloxacin, the closest analog with the same 1-cyclopropyl-6-fluoro-4-oxo-3-carboxylic acid core and C8 methoxy, has oral/IV AUC ratios of 0.91-0.92 in healthy volunteers, directly supporting F >= 20% for the query scaffold.",
      "card_ids": ["C87","C89"]
    },
    {
      "claim": "L4 absorption evidence shows ofloxacin/levofloxacin/pefloxacin/enoxacin are almost completely absorbed in humans (C141), a close fluoroquinolone analog had 92% oral absorption in rats despite low PAMPA (C165/C168), and the lowest class fraction-absorbed value is ciprofloxacin 71% in dogs (C132).",
      "card_ids": ["C141","C165","C168","C132"]
    },
    {
      "claim": "L5 efflux records confirm fluoroquinolones are P-gp/BCRP/MRP2 substrates and that inhibitors can raise exposure (C181/C187/C194/C218), but this mechanism does not imply low F: moxifloxacin is an efflux substrate yet has ~91% F (C183/C217 vs C87/C89), and gemifloxacin has high Caco-2 absorptive Papp of 1.2e-5 cm/s despite BCRP/MRP2 efflux (C175/C176).",
      "card_ids": ["C181","C187","C194","C218","C183","C217","C87","C89","C175","C176"]
    },
    {
      "claim": "No L5 record affirmatively demonstrates F < 20% for the query or a close analog; the mechanistic efflux evidence is not a direct oral-bioavailability result and is outweighed by direct human F and oral/IV exposure data.",
      "card_ids": ["C181","C194","C218","C87","C89","C141"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "high",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C181","C187","C194","C218","C211","C186","C201"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "The query-specific C7 piperidine-fluoroalkene-amine substituent is not directly represented in the records; its absorption/efflux behavior is inferred from moxifloxacin and other fluoroquinolone analogs.",
    "No query-specific efflux transporter assay or intestinal metabolism data are available; L5 records are for close analogs.",
    "Solubility of the exact query form is not measured; class solubility data are used as a proxy.",
    "Human F values for moxifloxacin are from 100 mg doses; the query dose and formulation are unknown."
  ],
  "decision_summary": "L5 gut-wall efflux records show fluoroquinolones are P-gp/BCRP/MRP2 substrates and that inhibition can increase exposure, but they provide no affirmative evidence of F < 20% for the query or close analogs. Direct human F and oral/IV AUC ratios for the class (ofloxacin ~80-100%, levofloxacin ~100%, trovafloxacin 87.6%, moxifloxacin 0.91-0.92) remain decisive. Prediction remains high; confidence remains high."
}

